import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Custom sidebar panels","description":"Create UIX sidebar links to Home Assistant pages and websites.","frontmatter":{"description":"Create UIX sidebar links to Home Assistant pages and websites."},"headers":[],"relativePath":"en/projects/uix/extras/custom-sidebar-panels.md","filePath":"en/projects/uix/extras/custom-sidebar-panels.md","lastUpdated":1794566710000}'),o={name:"en/projects/uix/extras/custom-sidebar-panels.md"};function r(i,e,c,p,d,l){return a(),s("div",null,[...e[0]||(e[0]=[n('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.1.0-beta.1</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/e28976f96db019e009c4c604e80c0885c1b3ea67" target="_blank" rel="noreferrer">e28976f</a>, reviewed 2026-11-08. Stable baseline on this site: <strong>9.0.0</strong>. Requires Home Assistant 2026.11.0 or later. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="custom-sidebar-panels" tabindex="-1">Custom sidebar panels <a class="header-anchor" href="#custom-sidebar-panels" aria-label="Permalink to &quot;Custom sidebar panels&quot;">​</a></h1><p>UIX can add custom entries to the Home Assistant sidebar that open another Home Assistant page or a website. This is useful for frequently used pages that are normally nested under Settings or another panel, or for providing a shortcut to a related web service.</p><p>Open <strong>Settings</strong> &gt; <strong>Devices &amp; services</strong> &gt; <strong>UI eXtension</strong> &gt; <strong>Configure</strong>, then select <strong>Manage custom sidebar panels</strong>. Add a panel by choosing its icon, entering its title, and entering its target.</p><p>Enable <strong>Admin required</strong> to restrict the sidebar panel to administrator accounts.</p><p>Targets can be either a Home Assistant navigation path beginning with <code>/</code>, such as <code>/config/dashboard</code>, or an absolute <code>http</code> or <code>https</code> URL. Other URL schemes are not accepted.</p><p>Enable <strong>Open in new tab (desktop only)</strong> to open a Home Assistant navigation path in a separate tab on desktop browsers. The current Home Assistant tab returns to the page you were viewing. In the Companion app, UIX instead navigates to the path within the app. Website URLs never use this option because they cannot open inside the Companion app.</p><div class="info custom-block"><p class="custom-block-title">New-tab availability</p><p>Opening a Home Assistant path in a new tab is subject to the browser&#39;s popup-blocking policy. UIX attempts to open the tab when the sidebar panel is selected, but cannot guarantee that the browser will permit it. When blocked, UIX opens the path in the current tab instead.</p></div><p>Each panel has a stable internal URL managed by UIX, so you can change its title, icon, and target without recreating it. Deleting a panel immediately removes its sidebar entry.</p><div class="tip custom-block"><p class="custom-block-title">Sidebar order</p><p>Home Assistant lets each user <a href="https://www.home-assistant.io/dashboards/dashboards/#reorganizing-items-in-the-sidebar" target="_blank" rel="noreferrer">reorder and hide sidebar items</a> from their profile.</p></div><div class="info custom-block"><p class="custom-block-title">Redirect behaviour</p><p>A custom sidebar panel is a redirect, not a duplicate page. When an in-app target is selected, UIX replaces the panel URL with the configured target so browser history does not contain an extra redirect step.</p></div>',11)])])}const g=t(o,[["render",r]]);export{b as __pageData,g as default};
